    destinationId: "dest-colorado",
    description:
      "South Platte Fly Shop is located along the banks of the South Platte River in the foothills southwest of Denver, serving as the primary outfitter for one of Colorado's most technical and rewarding tailwater fisheries. The shop sits in the small community of Pine, close to the famed Cheesman Canyon and Deckers stretches, waters known for their large, selective trout and challenging clear-water conditions that test even experienced anglers. This proximity to demanding fish is what defines the shop's character: the staff here are specialists in sight-nymphing, micro-pattern presentation, and the delicate leader-and-tippet configurations required to fool heavily pressured wild trout.\n\nThe fly selection reflects this precision-oriented approach, with a deep inventory of midges, Blue-Winged Olives, small stoneflies, and caddis patterns tied in sizes that would make many anglers squint. Tippet spools in diameters from 5X through 8X occupy a prominent rack, and the leader section is one of the most comprehensive in the state. Rods and reels lean toward the lighter end of the spectrum, with an emphasis on three and four-weight setups that maximize feel and delicacy on the clear, slow pools of the South Platte canyon. Guided trips focus almost exclusively on the South Platte drainage, including Cheesman Canyon, the Deckers section, Eleven Mile Canyon, and Spinney Mountain Ranch. The staff publishes a weekly conditions report that tracks water releases from Cheesman Dam, insect emergence timing, and recommended pattern rotations, giving visiting anglers the intelligence they need to fish productively from the moment they arrive at the trailhead.",
