    destinationId: "dest-idaho",
    description:
      "Silver Creek Outfitters has been the premier fly fishing destination in the Sun Valley area since the early 1970s, operating from a well-appointed shop on Main Street in Ketchum, Idaho. The shop draws its name from Silver Creek, one of the most famous and technically demanding spring creeks in the world, a slow-moving, crystal-clear waterway where large rainbow and brown trout feed selectively on tiny insects in full view of the angler. This proximity to Silver Creek defines much of the shop's identity, but the outfitting program extends across the entire Wood River Valley and beyond, covering the Big Wood River, the Big Lost River, and high-country lakes scattered throughout the Sawtooth and Pioneer ranges.\n\nThe retail floor reflects the upscale character of the Sun Valley community while remaining firmly rooted in practical fishing expertise. Rods and reels from the finest American and European manufacturers are displayed alongside a curated selection of wading gear, technical apparel, and accessories. The fly department is exceptional, with a deep inventory of spring creek patterns in sizes 18 through 26 that are rarely found outside of specialty tying catalogs. The guided trip program employs local professionals who have spent years learning the subtle currents and weed-bed structure of Silver Creek, and they are equally adept at floating the larger freestone rivers in the region. The shop hosts a full calendar of seasonal events, including casting clinics, fly tying workshops, and conservation fundraisers that draw participants from across the intermountain West. For anglers visiting Sun Valley, Silver Creek Outfitters is the natural starting point for any outing on the water.",
