    name: "The Fly Shop",
    destinationId: "dest-oregon",
    description:
      "The Fly Shop in Bend, Oregon, operates as one of the Pacific Northwest's most comprehensive fly fishing outfitters, drawing on the extraordinary concentration of diverse fisheries within driving distance of central Oregon. The Deschutes River, one of the premier steelhead and trout rivers on the West Coast, flows just minutes from the shop's door, while the Crooked River, Fall River, and the Metolius River are each within an hour. This geographic advantage, combined with a staff that collectively holds decades of guiding and competitive fly fishing experience, makes The Fly Shop an essential stop for anyone fishing the region.\n\nThe retail floor is spacious and methodically organized. A dedicated steelhead section carries the swung-fly rods, reels, lines, and patterns that are central to Deschutes fishing culture, while a separate trout department focuses on the lighter tackle and delicate presentations required for the Crooked River's technical tailwater and the Metolius spring creek. The fly selection is outstanding, with local patterns tied by regional experts alongside proven standards from major manufacturers. The guided trip program covers an unusually broad range of water types, from high-desert canyon rivers to Cascade Range stillwaters and coastal estuaries. The shop also serves as a hub for fly fishing education, offering multi-day schools, single-session casting clinics, and specialty workshops on topics like spey casting, entomology, and fly tying. A well-stocked online store extends the shop's reach to anglers across the country, but the in-person experience, with its firsthand river intelligence and hands-on gear advice, is what keeps local and visiting anglers returning season after season.",
