    description:
      "Gates Au Sable Lodge stands on the banks of the Au Sable River in Grayling, Michigan, and is one of the most historic fly fishing institutions in the Midwest. The lodge and its associated fly shop have been welcoming anglers to the Au Sable since 1972, but the property's connection to the river stretches back much further, rooted in a tradition of cold-water trout fishing that helped establish Michigan as one of the premier fly fishing states east of the Rockies. The Au Sable's Holy Water, a specially regulated catch-and-release stretch of river that flows directly past the lodge, is among the most celebrated trout streams in America.\n\nThe fly shop within the lodge carries everything an angler needs for the Au Sable and its tributaries, including the Manistee River, the North Branch of the Au Sable, and numerous smaller brook trout creeks. The fly selection is curated for the specific hatches that define Au Sable fishing: Hendricksons in spring, Brown Drakes and Hex mayflies in early summer, and Tricos through the late season. The canoe livery is a distinctive feature, renting the flat-bottomed Au Sable riverboats that have been the traditional watercraft on this river for over a century. Guided trips by riverboat or on foot cover both the trophy water near the lodge and more remote upstream sections. The lodge itself offers comfortable riverside accommodations, creating an all-in-one base for multi-day fishing trips. Evening hatches on the Holy Water, watched from the lodge porch with a drink in hand, are a quintessential Michigan fly fishing experience that draws anglers back year after year.",
