    description:
      "Sandy Moret's Florida Keys Outfitters in Islamorada, Florida, is the preeminent saltwater fly fishing shop in the United States, founded and operated by Sandy Moret, a casting instructor, guide, and angler whose name is synonymous with flats fishing in the Florida Keys. The shop occupies a prominent location on the Overseas Highway in the heart of the Sport Fishing Capital of the World, and it serves as the commercial hub for a fly fishing culture that revolves around the pursuit of bonefish, tarpon, and permit on the shallow, sun-drenched flats of the Florida Bay and Atlantic backcountry.\n\nThe retail inventory is tailored exclusively to saltwater fly fishing. Rods in eight through twelve-weight ratings line the walls, from fast-action graphite blanks designed for punching flies into a Keys headwind to more moderate tapers suited for delicate bonefish presentations on calm days. Reels are chosen for their sealed drag systems and corrosion resistance, non-negotiable requirements in the salt environment. The fly department is one of the finest saltwater collections anywhere, with a deep stock of Crazy Charlies, Gotchas, toad flies, tarpon streamers, and crab patterns in the colors and weights that local guides demand. The shop's guide referral program connects visiting anglers with a network of the best flats guides in the Keys, while the annual Florida Keys Fly Fishing School, led by Sandy Moret and guest instructors, has introduced thousands of anglers to the art of saltwater fly casting and sight fishing. For any fly angler making the pilgrimage to the Keys, this shop is the undisputed starting point.",
