    description:
      "Pacific Fly Fishers is a full-service fly shop located in the greater Vancouver area of British Columbia, serving as the primary outfitter for one of the most diverse fly fishing regions in North America. British Columbia's extraordinary range of fisheries, from the legendary steelhead rivers of the Skeena and Dean drainages to the trophy stillwater lakes of the Kamloops plateau and the coastal cutthroat streams of Vancouver Island, creates a demand for a shop with uncommonly broad expertise, and Pacific Fly Fishers delivers on that promise.\n\nThe retail floor is organized around the distinct fishing disciplines that British Columbia demands. The steelhead section is extensive, carrying two-handed rods, spey reels, shooting heads, and a wall of intruder-style flies and classic wet fly patterns designed for the province's world-class winter and summer steelhead runs. The stillwater department reflects BC's outstanding lake fishing tradition, with indicator setups, floating and sinking lines in various densities, and chironomid patterns in dozens of colors and sizes. A saltwater section covers the growing interest in fly fishing for Pacific salmon, sea-run cutthroat, and lingcod in the coastal waters of the Strait of Georgia. The shop's guide referral network spans the province, connecting visiting anglers with outfitters on remote rivers that require jet boat access or helicopter drops. Fly tying materials from leading global suppliers fill an entire wall, supporting the vibrant tying community in the Vancouver area. Regular workshops, film nights, and guest speaker events make the shop a gathering point for the regional fly fishing community.",
