    description:
      "Nervous Waters Fly Shop operates from Junin de los Andes, Argentina, in the northern Patagonian Andes, serving as a retail and outfitting hub for one of the most coveted trout fishing destinations on the planet. Junin de los Andes calls itself the Trout Capital of Argentina, and the claim is well supported by the extraordinary fisheries that surround it: the Chimehuin, Malleo, Collon Cura, and Alumine rivers flow through volcanic landscapes of stunning beauty, supporting populations of rainbow and brown trout that grow to remarkable sizes on a diet of pancora crabs, freshwater shrimp, and prolific insect hatches.\n\nThe shop stocks equipment tailored to the specific demands of Patagonian fly fishing, where long casts into stiff winds are a daily reality and the fish are powerful enough to test tackle and knots alike. Rods in the five through seven-weight range with fast actions dominate the selection, paired with reels that offer reliable drag performance and the capacity for long runs. The fly wall is a showcase of Patagonian patterns: large rubber-leg nymphs, pancora imitations, streamer patterns in olive and black, and dry flies that match the region's distinctive mayfly and caddis species. Wind-resistant leaders and heavy fluorocarbon tippets reflect the practical realities of fishing in some of the gustiest conditions any trout angler will encounter. The guided trip program connects visiting anglers with experienced local guides who hold the permits and local knowledge needed to access the best water, including private estancia-owned stretches that are otherwise closed to the public. For anglers making the journey to Patagonia's wild trout rivers, this shop provides the essential bridge between arrival and a productive day on the water.",
