    destinationId: "dest-belize",
    description:
      "Belize River Lodge Shop is the retail and outfitting arm of the storied Belize River Lodge, one of the oldest and most respected saltwater fly fishing operations in Central America. Located near the mouth of the Belize River just outside Belize City, the lodge and its shop have been introducing anglers to the extraordinary flats, mangrove lagoons, and offshore cayes of the Belizean coast since the 1960s. The fishing here targets a grand slam of tropical species, bonefish, tarpon, and permit, on shallow-water flats that stretch for miles under the Caribbean sun, and the shop is equipped to prepare anglers for every aspect of that pursuit.\n\nThe inventory is focused exclusively on saltwater fly fishing in tropical environments. Rods in eight through twelve-weight configurations line one wall, with an emphasis on the fast-action, wind-penetrating blanks that are essential for delivering weighted crab patterns to tailing permit in a stiff trade wind. Reels are selected for sealed drags and saltwater corrosion resistance, and the line selection includes tropical-coated products designed to remain supple and shoot cleanly in high heat. The fly department is the shop's crown jewel, stocking a comprehensive array of bonefish, tarpon, and permit patterns tied by local and international professionals who understand the specific conditions of the Belizean flats. Sun protection, polarized eyewear, and quick-dry apparel round out the offerings. The lodge's guide team, many of whom have fished these waters their entire lives, is available for both half-day and full-day outings, and the shop staff can advise on seasonal patterns, tide schedules, and which flats are fishing best on any given week.",
