    slug: "fish-on-nz",
    name: "Fish On NZ",
    destinationId: "dest-new-zealand",
    description:
      "Fish On NZ is a fly fishing outfitter based in Taupo, New Zealand, at the epicenter of the North Island's legendary trout fishing. Lake Taupo, the country's largest lake, is fed by dozens of rivers and streams that host massive spawning runs of rainbow and brown trout, and the Tongariro River, which enters the lake from the south, is the most famous trout river in the Southern Hemisphere. The shop has served visiting and local anglers for years, building a reputation for reliable advice, quality gear, and an intimate understanding of the seasonal rhythms that govern this unique volcanic fishery.\n\nThe retail selection is tailored to the specific demands of Taupo-region fishing. The fly wall emphasizes the nymph and wet-fly patterns that produce on the Tongariro's deep runs during the winter spawning migration, including a comprehensive range of glo-bugs, hare-and-coppers, and bead-head nymphs in the sizes and weights that local guides insist upon. Dry-fly and streamer sections cater to the summer months when fish move into the smaller tributary streams and feed actively on the surface. Rods in the five through seven-weight range dominate the selection, reflecting the size of fish that regularly exceed five pounds and occasionally reach double digits. The guided trip program covers the Tongariro, Tauranga-Taupo, Hinemaiaia, and Waitahanui rivers, as well as lake-based fishing from boats and kayaks. The staff provides daily river conditions and can help visiting anglers navigate the New Zealand fishing license system, which is straightforward but unfamiliar to most international visitors. For any angler visiting the Taupo region, this shop provides the local grounding that turns a scenic holiday into a memorable fishing adventure.",
