    name: "Henry's Fork Anglers",
    destinationId: "dest-idaho",
    description:
      "Henry's Fork Anglers sits at the nerve center of one of the most celebrated dry-fly fisheries in the world, positioned along US-20 in Island Park, Idaho, just minutes from the Railroad Ranch section of the Henry's Fork and the northern boundary of Harriman State Park. The shop has built its reputation over decades around a single, exacting standard: genuine expertise in fishing the Henry's Fork, a river so demanding and so rewarding that it attracts serious anglers from every continent willing to endure technical refusals in exchange for the possibility of fooling a twenty-inch rainbow on a size 22 PMD.\n\nThe Henry's Fork is unlike most trout rivers. Its spring-fed flows are gin-clear and nearly current-free in stretches, giving the fish ample time to scrutinize every fly that drifts overhead. The trout here are not simply large; they are educated, often having rejected dozens of incorrect presentations in a single season. The staff at Henry's Fork Anglers are students of this water in the truest sense, tracking the progression of hatches from early spring Baetis through the iconic salmon fly and Green Drake windows and into the spinner falls of late summer with the kind of precision more common to an entomologist than a retail clerk.\n\nThe shop carries a carefully curated selection of flies tied specifically for Henry's Fork conditions, including proprietary patterns developed by local tiers who have spent years reverse-engineering the feeding behavior of the railroad ranch fish. Rods, reels, and lines are chosen for their performance in the long, delicate presentations that Henry's Fork demands, and the guide staff is among the most knowledgeable on the river. Whether you are pursuing your first Henry's Fork riseform or returning for your twentieth season, this is where the conversation about the river begins.",
