    destinationId: "dest-idaho",
    description:
      "TRR Outfitters operates the Henry's Fork Fly Shop in Island Park, the flagship retail location for Three Rivers Ranch, one of Idaho's most established multi-river outfitting operations. The shop takes its name from the confluence of the three great drainages it serves — the Henry's Fork, the South Fork of the Snake, and the Teton River — each offering a distinctly different angling experience within a half-day's drive. This geographic range gives TRR Outfitters a breadth of programming that few regional shops can match.\n\nThe Island Park location sits at the northern gateway to the Henry's Fork corridor, making it a natural staging point for anglers headed to the Railroad Ranch or the slower, spring-fed reaches upstream. The shop is well stocked with locally tied patterns, technical dry flies appropriate for selective Henry's Fork fish, and a full complement of streamer and nymph patterns for the higher-gradient sections of the river below Ashton. The guide roster draws from a pool of professionals with deep experience on each of the three rivers, and multi-day packages can be arranged to sample multiple drainages in a single trip.\n\nBeyond guiding and retail, TRR Outfitters maintains a genuine connection to the local angling community, contributing to conservation efforts on the Henry's Fork watershed and supporting the catch-and-release ethic that keeps the fishery healthy year after year. Anglers looking for a shop that can orient them quickly to the opportunities of the Upper Snake River region will find the Island Park staff highly capable of putting together a thoughtful and productive itinerary.",
