    destinationId: "dest-idaho",
    description:
      "The Ashton location of TRR Outfitters serves as the southern anchor of Three Rivers Ranch's outfitting network, positioned along US-20 in the agricultural town of Ashton, Idaho, at the gateway to the lower Henry's Fork canyon. This stretch of the river below Ashton Dam is a fundamentally different fishery from the spring-creek character of the upper Henry's Fork — bigger flows, faster water, and a mix of rainbow and brown trout that responds well to both dry flies and streamers depending on the season.\n\nAshton's proximity to the South Fork of the Snake River and the Teton River adds significant versatility to the outfitting program based here. The South Fork is one of the most productive float fisheries in the American West, a freestone river with a robust population of large cutthroat and brown trout that responds readily to attractor patterns and hopper-dropper rigs through the summer months. The Teton River, quieter and more intimate, offers classic wade fishing in a mountain setting that is dramatically undervisited relative to its quality.\n\nThe Ashton shop maintains a focused inventory built around the specific flies, lines, and leader configurations that produce results on these three rivers. Staff are well versed in the seasonal rhythms of each drainage, and the guide operation draws on professionals who specialize in the lower Henry's Fork canyon as well as the South Fork float program. For visiting anglers who want to cover a variety of water types without driving long distances between outings, the Ashton location provides a practical hub with genuine expertise across all of them.",
