    description:
      "Drift Lodge & Fly Shop operates from a prime position on US-20 in Island Park, Idaho, combining comfortable lodging with a well-appointed fly shop and guided fishing program focused on the exceptional trout waters of the upper Henry's Fork watershed. The lodge concept is built around simplicity: give visiting anglers a clean, well-equipped base of operations close to the water, a knowledgeable shop stocked with the flies and gear they actually need, and access to guides who know the river intimately.\n\nThe Henry's Fork water accessible from Island Park ranges from the technical, flat-water spring creek character of the Railroad Ranch section in Harriman State Park to the faster, more muscular flows below the Box Canyon, where large rainbow trout hold in heavy current and respond readily to stonefly nymphs and large dry flies during the salmon fly hatch. Drift Lodge's guides are fluent in both styles of fishing and can tailor each outing to match conditions and angler ability. First-time visitors to the Henry's Fork benefit enormously from having a guide who can explain the river's particular demands before the first cast is made.\n\nThe fly shop maintains a focused inventory rather than trying to be all things to all anglers. The fly selection leans toward the patterns that are actually working on the local water, updated regularly based on staff reports from the day's fishing. Rods and reels are chosen for their suitability to Henry's Fork applications, with an emphasis on tools that perform well in the delicate, precise casting that selective fish in clear water demand. For anglers looking to stay close to world-class fishing without the overhead of a full-service destination lodge, Drift Lodge provides an ideal balance.",
