    description:
      "Campfire Lodge Fly Shop occupies a prime position on the banks of the Madison River just outside West Yellowstone, Montana, combining a fully stocked fly shop with comfortable lodge accommodations in a setting that places guests within easy walking distance of some of the most productive trout water in the country. The Madison River here is a wide, powerful freestone stream running cold and clear out of Yellowstone National Park, carrying large brown and rainbow trout that respond to a wide range of presentations throughout the season.\n\nThe fly shop at Campfire Lodge is built around the practical needs of anglers fishing the Madison and the surrounding waters. The fly selection covers the hatches that define the Madison season — salmonflies and golden stones in late June, the prolific caddis hatches of midsummer, the trico spinner falls of August, and the streamer fishing that produces some of the largest fish of the year in September and October as browns begin moving ahead of the spawn. Staff members fish the river themselves and update their recommendations based on what they have personally observed, not industry inventory lists.\n\nGuided trips through Campfire Lodge cover the upper Madison from West Yellowstone down through Quake Lake and into the Bear Trap Canyon, providing access to varying character and fish populations along one of Montana's most storied rivers. The lodge accommodations range from streamside cabins to more expansive family units, and the combination of on-site lodging and expert fishing services makes Campfire Lodge a natural choice for groups and families who want to organize their entire stay around the river.",
