    description:
      "Jacklin's Fly Shop is one of the oldest and most storied fly fishing establishments in West Yellowstone, founded by Bob Jacklin, a professional fly tier, guide, and author whose contributions to the sport span more than half a century. The shop has operated from Yellowstone Avenue since the late 1960s, accumulating an institutional knowledge of the greater Yellowstone area's fisheries that is difficult to replicate and impossible to replace. Bob Jacklin's career as a fly tier and educator placed him in extended conversation with the sport's greatest thinkers, and the shop continues to reflect the serious, craft-oriented ethos he established.\n\nBob Jacklin is best known for developing the Rio Grande King Trude and numerous other productive patterns for Greater Yellowstone waters, and the fly bins at Jacklin's carry a comprehensive selection of his signature ties alongside current-season patterns from a rotation of local tiers who fish the same rivers their flies are tied to imitate. The shop's approach to the fly selection is methodical rather than trend-driven: what works on the Madison in late June, what fish in the Firehole are eating in September, what the Yellowstone Park cutthroat are keying on in the high summer — these questions drive the inventory.\n\nThe guide program at Jacklin's draws on decades of accumulated river knowledge, with professionals capable of navigating the specific regulations and access requirements of Yellowstone National Park alongside the public water of the Madison and Gallatin corridors. Bob Jacklin himself has guided fishing trips in this region for longer than most of the other shops in town have existed, and his influence on how the shop thinks about guiding — patient, educational, attentive to the angler's development as much as the day's catch — remains evident throughout the operation.",
