    description:
      "South Branch Outfitters sits on the banks of the South Branch of the Raritan River in Califon, New Jersey, positioned as the definitive home base for cold-water anglers in Hunterdon County and the broader limestone corridor that stretches across the state's northwest highlands. The shop was formerly known as Shannon's Fly & Tackle before transitioning to its current form as a veteran-owned, community-driven operation — a change in name that brought a renewed emphasis on accessibility and inclusion without softening the serious fly fishing focus that has always defined this location's reputation on the South Branch.\n\nThe South Branch of the Raritan is New Jersey's most celebrated wild trout fishery, and the shop's position in Califon puts it within minutes of the Ken Lockwood Gorge, the state's premier catch-and-release section, where wild brown and rainbow trout rise selectively to Hendrickson duns in April and sulphurs throughout May and June. The guides who work out of South Branch Outfitters know the gorge's rhythms intimately — the seams where fish stack during hatches, the feeding lanes that reward a careful upstream approach, the evenings in late May when the light goes golden and the sulphurs begin coming off in number. Beyond the South Branch, the shop is well-positioned to direct anglers to the Musconetcong, the Pequest, and the North Branch of the Raritan, rounding out a day of exploring into a genuine tour of New Jersey's most productive trout country. The gear selection at South Branch Outfitters reflects the waters it serves: precise rods, quality tippet, and a fly selection built around the hatches that drive fishing on eastern limestone streams.",
