    description:
      "Tight Lines Fly Fishing in Pine Brook, New Jersey, serves the dense concentration of fly fishers in the Morris County and Passaic River watershed area — a region that includes the Musconetcong River, the Rockaway River, the Whippany, and the Passaic's cold headwater tributaries that course through the forested ridges of the Highlands before dropping toward the piedmont. The shop on Main Street has built a following among northern New Jersey anglers who want the same quality of gear and expertise available at shops in more celebrated fly fishing destinations without the four-hour drive.\n\nThe gear selection at Tight Lines is genuinely comprehensive by any measure — Sage, Scott, Winston, Hardy, Simms, Patagonia, Rio, Redington, Abel, Ross, and Hatch are all represented, a roster that would be impressive in any fly shop in the country and is remarkable for a shop serving a state most anglers don't associate with serious fly fishing. The staff understands the specific character of North Jersey trout water: streams that run cold in spring and early summer but warm under pressure by July; limestone-influenced sections where wild browns feed selectively on tiny midges; marginal tailwaters and reservoirs that hold overlooked populations of quality trout for the angler willing to investigate. Guided trips cover the Musconetcong and the Raritan's tributary network, and the shop's connections to the Trout Unlimited chapter structure in North Jersey give it a conservation credibility that extends beyond retail.",
