    name: "Golden Stone Outfitters",
    destinationId: "dest-new-jersey",
    description:
      "Golden Stone Outfitters takes its name from the golden stonefly — the Perlodidae species that emerge on New Jersey's best limestone creeks and freestone streams each spring, a hatch that signals the real beginning of the trout season for the anglers who know to look for it. The shop's full-service model covers everything from quality tackle and fly selection to guided trips across the state's most productive cold-water streams, with a focus on the kind of place-specific knowledge that separates useful local expertise from generic fly fishing advice.\n\nNew Jersey's best trout streams don't advertise themselves. The limestone-influenced sections of the Musconetcong hold wild brown trout in their cold upper reaches that feed with the selectivity of spring creek fish, demanding careful tippet selection and precise presentation in clear, slow water. The South Branch of the Raritan's Ken Lockwood Gorge section offers wild trout in a dramatic hemlock-canyon setting that surprises visitors expecting the dense development that surrounds it. The Big Flatbrook in the northwest corner of the state is a legitimate freestone wild trout river, its headwaters supporting native brook trout populations that remind anglers how productive this region was before industrial-era alterations to the watershed. Golden Stone Outfitters navigates this geography with the authority that comes from fishing it seriously — providing access to water and insight that independent discovery would take seasons to accumulate. For the serious eastern angler who wants to fish New Jersey properly, this shop is the right starting point.",
