    slug: "jackson-hole-fly-company",
    name: "Jackson Hole Fly Company",
    destinationId: "dest-wyoming",
    description:
      "Jackson Hole Fly Company was built on a premise that challenges the conventional fly fishing retail model: that high-performance gear doesn't require a luxury price, and that anglers who fish hard under demanding conditions deserve quality equipment without paying a premium simply for a name on a rod blank. The shop designs and builds its own rods, reels, flies, and accessories — testing every product under the Tetons on the Snake River and the other waters of the Jackson Hole valley before it goes into a customer's hands. The result is a catalog of tackle that earns its place in the box through field performance rather than marketing.\n\nThe waters around Jackson Hole have always attracted serious anglers willing to invest in quality gear, and the Snake River's population of fine-spotted Snake River cutthroat trout is among the most visually striking and aggressively opportunistic trout anywhere in the Rocky Mountain West. The float through the cottonwood-lined canyon from Pacific Creek to Moose is one of the defining experiences in American fly fishing, with the cutthroats rising readily to large dry flies and the Teton Range rising above the river corridor in a way that makes every drift feel significant. Jackson Hole Fly Company's online-first model with local pickup gives visiting anglers the flexibility to stock up efficiently before a trip, and the shop's deep knowledge of local water extends to guided trip recommendations and current conditions across the Snake River system and into the park. For the angler who wants to fish the Snake River with the right gear at a fair price and the local knowledge to use it effectively, Jackson Hole Fly Company offers a compelling alternative to the traditional tackle shop experience.",
