    description:
      "Westbank Anglers occupies one of the most enviable positions in American fly fishing retail — on the North Moose Wilson Road in Wilson, Wyoming, at the base of Teton Pass on the west bank of the Snake River where the canyon begins to open and the fish counts start to climb. The shop has been a fixture in the Jackson Hole fly fishing ecosystem for decades, serving as a point of departure for float trips on the Snake River, guided wade trips into Grand Teton National Park, and multi-day excursions that reach the Green River, the Salt River, and the park's less-visited interior waters.\n\nWhat distinguishes Westbank Anglers in a valley full of quality fly shops is the combination of location and institutional knowledge. The Wilson shop sits within walking distance of prime Snake River access, and the guide staff includes some of the valley's most experienced river readers — guides who have floated the canyon from Pacific Creek to Moose hundreds of times, who understand how the river's fine-spotted cutthroats shift their feeding lanes through the season, and who know which channels are fishing in mid-August when the main current slows and the fish move to the edges. The shop's gear selection is focused and high-quality, carrying the tackle appropriate to the technical demands of the Snake River and the adjacent park waters rather than attempting to stock every product category. For the serious angler visiting Jackson Hole, Westbank Anglers is the natural base of operations — a place where the conversation about where to go and what to fish begins before the waders go on.",
