    description:
      "Grand Teton Fly Fishing operates at the intersection of two of America's most celebrated wild trout ecosystems — the Snake River corridor through Jackson Hole and the interior waters of Grand Teton and Yellowstone National Parks. The operation's focus on guided trips inside the parks sets it apart from shops that concentrate on the Snake River float experience alone, and the result is a guide roster with genuine backcountry expertise: the ability to put anglers on park waters that demand a permit, local knowledge, and physical effort to access, but reward that investment with wild cutthroat trout in settings of extraordinary natural beauty.\n\nFull-day, half-day, and custom float trips along with walk-and-wade experiences give visiting anglers the flexibility to build a Jackson Hole fishing itinerary around their ability level and available time. The Snake River float from Pacific Creek to Moose is the defining Jackson Hole experience — the fine-spotted cutthroats, the cottonwood canopy, the Teton skyline rising above the river corridor — and Grand Teton Fly Fishing's guides navigate it with the authority of people who have rowed it in every season and every water condition. The park's interior waters, accessible only to those with proper permits and the knowledge to navigate the backcountry approach, add another dimension to what GTFF offers: native Yellowstone cutthroat trout in the park's headwater streams and the Lamar Valley, fish that have never been stocked and live in drainages that look the way all western rivers looked before the twentieth century. For the angler who wants to experience both the classic Snake River float and the park's lesser-known backcountry, this operation covers both ends of the Jackson Hole fly fishing spectrum.",
