      "Snake River Angler operates with a clarity of focus rare in the modern fly fishing shop landscape: the Snake River, the Green River, the Gros Ventre, and the waters of Grand Teton and Yellowstone National Parks — and the guided trips that put serious anglers on all of them in the most productive way possible. The downtown Jackson address places the shop at the center of the valley's fishing ecosystem, but the operation's real identity is in its guides and the intimate knowledge they carry of the specific rivers named in the shop's business.\n\nThe Snake River through Jackson Hole is among the most photogenic float fishing experiences in North America, the fine-spotted cutthroats rising to dry flies beneath a cottonwood canopy with the Teton Range dominating the western horizon. Snake River Angler's guides have rowed this canyon more times than most shops can count, and the depth of their understanding shows in the quality of the float experience they deliver: the ability to read the river's ever-shifting structure, to position the boat precisely for the best casting angle, and to anticipate where the fish will be feeding at each stage of the day as hatches move through the canyon. The Green River in Wyoming adds a different dimension — larger fish, more technical nymphing in places, the sage-covered high desert replacing the Teton's alpine backdrop — and the park waters provide backcountry access to native cutthroat populations that require a permit and local knowledge to reach. For the angler who wants a guide operation built entirely around the rivers that define Jackson Hole fly fishing rather than a retail shop that also offers trips, Snake River Angler is the answer.",
