    description:
      "Teton Fly Fishing is a boutique guide operation built around the personal expertise of its founder, providing the kind of small-boat intimacy and individual attention that only a carefully managed single-guide or small-team operation can offer. Based in Jackson and covering the Snake River, its tributaries, and the interior waters of Grand Teton and Yellowstone National Parks, the operation prioritizes depth of experience on fewer rivers over the broad coverage of the valley's larger guide services. Every guided day is shaped by a guide who has fished the water that morning, who understands current conditions from recent observation rather than seasonal assumption, and who can adapt the day's plan in real time as conditions shift.\n\nThe Snake River's fine-spotted cutthroats are the primary draw for most visiting anglers, and the float from Pacific Creek through the Oxbow Bend to Moose delivers on every promise that the Jackson Hole fly fishing reputation implies. But the waters surrounding that float — the side channels, the beaver pond complexes, the park's interior streams accessible only on foot — offer a different fishing experience that rewards the angler willing to leave the boat. Teton Fly Fishing's guides know these secondary waters as well as the main river, and a guided day can move between the float and a wade approach to a specific spring creek or backcountry tributary depending on what conditions favor. The Teton Range rising above every cast is a constant reminder that this is extraordinary country, and the fish that live in its drainages — native Snake River fine-spotted cutthroats in the main channels, Yellowstone cutthroats in the park's headwaters — are extraordinary in their own right.",
