    destinationId: "dest-idaho",
    description:
      "Picabo Angler holds a position in Silver Creek fly fishing that no other shop can claim: it sits on the banks of the creek itself, at the edge of the Nature Conservancy's Silver Creek Preserve, in the tiny agricultural community of Picabo that gave the Olympic skier Picabo Street her name. The shop is the only outfitter operating directly on Silver Creek's most celebrated section, and the significance of this location extends beyond convenience — guides and staff who work at Picabo Angler fish the creek before and after every guided day, observing hatch activity, noting where the large fish are holding, and accumulating the kind of current, granular knowledge about Silver Creek's behavior that cannot be acquired any other way.\n\nSilver Creek is one of the most technically demanding spring creeks in the American West. The flat, clear water of the preserve section exposes every mistake in leader construction, fly selection, and presentation, and the rainbow and brown trout that have survived multiple seasons on this water feed with the precision and caution of fish that have been educated by generations of fly fishers from around the world. The hatches are specific and short-lived: tiny Baetis in early season that require size-20 patterns and 6X tippet at minimum; PMD hatches in mid-summer that bring the largest fish up in the evening; blue-winged olives in fall when cooler temperatures extend the feeding windows and solitude returns to the preserve section. Picabo Angler's fly selection is calibrated to these hatches with precision, and the guides who take clients onto the creek are Silver Creek specialists in the fullest sense — they have fished it in every condition, every season, and understand it with the authority that only years of dedicated attention to a single piece of water can produce.",
