    description:
      "Solitude River Trips, based in Salmon, Idaho, is one of the most respected wilderness outfitters in the American West — a company built on the belief that some of the finest fly fishing on Earth exists at the end of long trails and down wild rivers that only drift boats and rafts can reach. Their specialty is the Middle Fork of the Salmon River, a designated Wild and Scenic waterway that drops nearly 3,000 feet through the Frank Church–River of No Return Wilderness — the largest wilderness area in the continental United States. The Middle Fork is breathtaking in every respect: crystalline water, dramatic canyon walls, natural hot springs, native westslope cutthroat rising freely to dry flies, and a remoteness that strips away everything except the river and the fish.\n\nSolitude also operates on the Main Salmon — the \"River of No Return\" — offering multi-day float expeditions through the second deepest canyon in North America. Both rivers deliver wilderness camping under dark-sky conditions, whitewater through classic western rapids, and exceptional dry fly fishing for wild cutthroat that have never seen a synthetic fly. The outfitter's guides carry deep river knowledge accumulated over decades and combine whitewater expertise with serious fly fishing instruction and strategy. Equipment is top-tier and camp cuisine rivals what you'd expect at a fine lodge. For the angler who measures a trip not in fish counts but in days of genuine wildness, Solitude River Trips offers something irreplaceable.",
