      "Wind River Outfitters operates at the edge of the wild in Dubois, Wyoming — a small town perched at the gateway to the Wind River Mountains and the vast high-altitude fishing country that lies beyond. The Winds contain more than 1,300 lakes and hundreds of miles of streams above 9,000 feet, holding populations of wild golden trout, cutthroat, brook trout, and grayling that have been isolated from the modern world since the last ice age. This is backpacking and horsepacking country, where the fishing improves with every mile gained from the trailhead and solitude is the standard rather than the exception.\n\nWind River Outfitters specializes in high-country pack-in expeditions — either by foot or by horse — that deliver anglers to remote lake basins and stream drainages that rarely see fishing pressure. The outfitter also covers the Wind River below Boysen Reservoir, where large brown trout congregate in the tailwater, and the warm-water fisheries of the Bighorn Basin within reach of Dubois. The shop itself stocks high-country specific gear with an emphasis on lightweight packable equipment, durable waders suited to cold mountain lakes, and a fly selection that covers the unique hatches of alpine environments: small Baetis, damselflies, midges, and the small stimulator and elk hair patterns that draw cutthroat and goldens from crystal clear water. For the angler willing to earn their fish, Wind River Outfitters is the key that opens one of the finest wilderness fishing landscapes in North America.",
