    description:
      "The Muskegon River Fly Shop in Newaygo, Michigan sits at the heart of one of the Great Lakes region's finest and most diverse fly fishing rivers. The Muskegon flows cold and clear from Croton Dam downstream through a broad valley of hardwood ridges and sandy runs, producing fishing that rivals anything the Midwest has to offer across every season. In summer, the river runs a prolific Hexagenia limbata hatch — the Hex — that brings the largest brown trout in the river to the surface after dark in one of fly fishing's most dramatic annual rituals. Steelhead ascend from Lake Michigan in spring and fall, filling the river with sea-run fish that drive anglers from across the country to stand in its gravel-bottomed runs. And through it all, a healthy population of resident brown trout and resident rainbow provide year-round technical fishing for anglers who want water to themselves.\n\nThe shop is staffed by guides and anglers who have spent their careers on the Muskegon, developing the kind of nuanced, season-by-season knowledge that translates directly into better days on the water for clients. Guided wading and drift boat trips cover the trophy stretch from Croton Dam to below Newaygo, and the fly selection is one of the deepest and most current on any Great Lakes river. The Hex pattern selection alone is worth the visit — dozens of variations tied specifically for the Muskegon's particular insects. Gear, waders, and apparel from leading manufacturers round out an operation that takes the Muskegon seriously as one of America's finest trout rivers.",
