      "Jack Trout Fly Fishing, based in McCloud at the foot of Mount Shasta, is one of Northern California's most recognized guide operations — built around a guide whose legal name reflects a lifelong obsession and whose knowledge of the region's rivers is, at this point, encyclopedic. Jack has guided on the Upper Sacramento, McCloud, Klamath, and Trinity rivers for over three decades, accumulating the kind of water-specific intelligence that only comes from watching the same hatches, pools, and currents in every season across thirty years. He is as much an ambassador for Northern California trout fishing as he is a guide, appearing in regional media and operating a small fly fishing resort that serves as a base for exploring the remarkable diversity of water within an hour of his doorstep.\n\nThe Upper Sacramento below Box Canyon Dam is Jack's home water — a cold, clear freestone river designated as a wild trout corridor for much of its length, carrying a hatch calendar that runs from tiny midges in winter through golden stoneflies in July and into fall blue-winged olives. The McCloud River, flowing through private land and a Nature Conservancy preserve, is one of the most pristine wild trout rivers in California; access requires permitted guided entry that Jack has cultivated over decades of relationship building. International programs — Belize bonefish flats, Patagonian rivers, Iceland — round out an operation that serves anglers from complete beginners to seasoned travelers seeking a knowledgeable Northern California partner for any water on earth. The shop provides full retail, local fly selection, and equipment rental alongside a guide roster that covers every skill level and ambition.",
