    destinationId: "dest-california",
    description:
      "Ted Fay Fly Shop stands on the main street of Dunsmuir, California, as both a working fly shop and a living monument to one of the most consequential figures in Northern California fly fishing history. Ted Fay (1915–1998) guided on the Upper Sacramento River for nearly five decades, pioneering the catch-and-release ethic on these waters long before it became common practice and helping establish the conservation culture that made the river the world-class trout fishery it remains today. He was among the first guides in California to advocate with genuine conviction for wild trout preservation and the return of wild fish, a philosophy that shaped generations of anglers who passed through his boats. The shop that bears his name honors that legacy with the seriousness Fay himself brought to the water.\n\nThe Upper Sacramento below Box Canyon Dam at the foot of Mount Shasta is one of the most underrated wild trout rivers in the American West. Cold, clear, and regulated as a wild trout corridor for much of its length, the river holds dense populations of wild rainbow trout in riffles, runs, and pocket water that respond to a hatch calendar extending from February midges through October blue-winged olives. The golden stonefly emergence in June and July produces some of the most exciting dry fly fishing in California — aggressive rainbows rising to bushy dry flies in fast, bright water while the volcanic cone of Shasta stands above the canyon rim. Ted Fay Fly Shop stocks a comprehensive selection of proven Upper Sacramento patterns, carries the major rods, reels, and wading systems, and operates a guide service that continues in the spirit Fay established: patient, conservation-minded, and deeply knowledgeable about the river he loved.",
