    destinationId: "dest-maine",
    description:
      "Lakewood Camps sits on the shore of Rangeley Lake in the heart of western Maine's most historically significant fly fishing territory, operating as a traditional sporting camp for over a century in a region that holds a foundational place in the American fly fishing story. The Rangeley Lakes — Rangeley, Mooselookmeguntic, Richardson, Kennebago — formed the epicenter of a nineteenth-century brook trout and landlocked salmon fishery of national fame, drawing sport anglers north from Boston and New York on overnight trains to pursue fish of a size that existed almost nowhere else in New England. Carrie Stevens, working from a camp near the Rangeleys, tied the Gray Ghost streamer and dozens of other landlocked salmon patterns that remain canonical more than a century later. Theodore Gordon drew inspiration from these waters. The dry fly tradition that would shape all of American trout fishing was partly born here, in these cold, clear, northern lakes.\n\nLakewood Camps preserves that lineage with an authenticity that has become increasingly rare: individual log cabins on the water's edge, guided canoe trips on the lake and its tributary streams, meals served in a central lodge, and the unhurried rhythm of a fishing day organized around the dawn rise. Resident guides — lifelong Mainers with generational knowledge of these ponds, rivers, and salmon lies — are the soul of the operation. The Kennebago River, which flows into Rangeley Lake, offers exceptional landlocked salmon fishing during spring and fall runs. High-elevation brooks and remote ponds accessible by canoe portage hold native brook trout in freestone water of pristine clarity. For anglers who want to fish the waters that made New England fly fishing legendary and understand why it mattered, Lakewood Camps is the essential address.",
