    description:
      "Trout Creek Flies operates out of Driggs, Idaho, on the quiet western side of the Teton Range — the Teton Valley side that locals and serious anglers have long favored for its comparative solitude, accessible water, and the extraordinary quality of the spring-fed and freestone streams within easy reach. The shop anchors the fly fishing community in a valley that has resisted the overcrowding that has affected the Wyoming side of the mountains, and the staff carries the local knowledge that only comes from fishing the same water in every season: where the South Fork cutthroat stack up during the pale morning dun emergence, how the Teton River fishes in late August when the terrestrial season peaks, and which spring creek bends hold the largest, most selective fish.\n\nThe shop covers the full spectrum of Teton Valley and eastern Idaho fishing: the Teton River from its headwaters through the canyon below Teton Dam, the South Fork of the Snake for its legendary floating and large brown trout, and the Henry's Fork within a short drive for its famous technical dry fly fishing on the Railroad Ranch. The inventory is curated for local conditions — Pale Morning Duns and Callibaetis for the Teton's spring-fed sections, streamers and nymphs for the South Fork's heavy water, and precise Ephemerella and Tricorythodes patterns for the Henry's Fork's educated fish. Guided half-day and full-day trips serve all skill levels, and multi-day itineraries cover the region's diverse fisheries for anglers who want to experience the range of what eastern Idaho fly fishing offers. For visitors who want Teton-quality water without the Wyoming crowds, Driggs is the insider option — and Trout Creek Flies is the reason to go.",
