      "NM Fly Fishing Guides is a New Mexico-based guide service and outfitter operating out of Albuquerque with coverage extending across the state's premier fly fishing waters. Rather than tethering itself to a single watershed, the operation was built to serve as a comprehensive gateway to New Mexico's remarkably diverse trout fishery — from the world-renowned San Juan River tailwater near Navajo Dam in the northwest to the wild trout streams of the Jemez Mountains, the Rio Grande Gorge north of Taos, and the high-elevation cutthroat water of the Pecos Wilderness. This breadth of coverage makes the service especially valuable for out-of-state anglers whose travel schedules require flexibility.\n\nThe guide roster consists of experienced New Mexico natives who've spent careers learning the rhythms of these desert and mountain rivers. San Juan trips focus on the technical midge and nymph fishing that defines the tailwater below Navajo Dam — one of the most productive dry-fly fisheries in the Southwest with 14,000 fish per mile documented in some sections. Rio Grande trips venture into the dramatic gorge country, while mountain stream expeditions access the small streams and wilderness lakes that hold native Rio Grande cutthroat trout. The operation offers gear rentals, casting instruction, and full-service trip logistics for visiting anglers who prefer to arrive and fish without the burden of extensive pre-trip preparation.",
