    description:
      "Lee's Ferry Anglers has occupied its singular post at Marble Canyon, Arizona, since 1988, serving what many serious trout anglers consider one of the most extraordinary tailwater fisheries on Earth. The Colorado River below Glen Canyon Dam at Lee's Ferry — a 15-mile stretch before the canyon narrows into the Marble Canyon of Grand Canyon — holds an extraordinary density of massive rainbow trout sustained by the cold, clear, algae-rich flows from the depths of Lake Powell. Fish in the 3- to 10-pound range are routine; fish exceeding 20 pounds are caught every season. In a landscape of soaring red canyon walls and stark desert silence, it produces fishing that bears no resemblance to anything else in North America.\n\nThe shop is staffed by guides and anglers who have spent their careers on this one stretch of river, accumulating the specialized knowledge that the Lee's Ferry fishery demands — precise midge and annelid presentations, specific tippet weights, an understanding of the dam's daily release schedules and their downstream effects on feeding behavior. The guide program is among the most respected in the Southwest, with seasoned professionals who've spent thousands of days reading the Colorado's gin-clear currents. Lee's Ferry Anglers stocks the full complement of gear, flies, licenses, and equipment needed to fish here, along with the Cliff Dwellers Lodge and camping facilities managed in coordination with the shop. This is a destination unto itself, and the shop is the essential gateway to it.",
