    description:
      "WMAT Outdoor Recreation is the tribal recreation department of the White Mountain Apache Tribe, administering access to one of the most exceptional and exclusive trophy trout fisheries in the American Southwest. The White Mountain Apache Tribe manages approximately 400,000 acres of pristine mountain terrain in east-central Arizona, including a network of trophy lakes and streams that are closed to the general public and accessible only through tribal recreation permits. The fishery includes Show Low Creek, the North Fork of the White River, and a series of carefully managed trophy trout lakes where fish regularly reach 5 to 15 pounds in a setting of tall ponderosa pines, volcanic meadows, and blue-ribbon spring creeks at elevations between 6,000 and 9,000 feet.\n\nThe department sells day-use and seasonal tribal recreation permits, rents fishing gear and float tubes, and operates bait and tackle concessions at several key access points. Unlike a commercial fly shop, WMAT Outdoor Recreation is a stewardship organization — permit fees fund conservation programs, habitat restoration, and hatchery operations that sustain the fishery. Anglers fishing tribal waters must possess a valid Arizona fishing license in addition to the tribal permit, and all regulations are strictly enforced. The quality of the experience reflects the tribe's disciplined catch-and-release management on designated trophy sections, producing a fishery that holds its own against anything in Montana or Wyoming.",
