    description:
      "Fly Fishing the Smokies is the definitive outfitter for one of the most distinctive and demanding fly fishing environments in North America — the wild trout streams of Great Smoky Mountains National Park and the surrounding Cherokee National Forest and Nantahala National Forest watersheds. Based in Bryson City, North Carolina, in the heart of the Smokies' western gateway, the shop occupies a position of unmatched access to hundreds of miles of roadless, boulder-pocket mountain streams harboring wild rainbow trout, brown trout, and in the highest-elevation headwaters, the native Appalachian brook trout that represent one of the rarest and most ecologically precious fish populations on the continent. No part of this region is easy to fish — short casts, high-sticking technique, careful approach, and exact drift control are rewarded while casting laziness is punished immediately by tight canopy and technical currents.\n\nFly Fishing the Smokies guides have accumulated thousands of combined days in the park and surrounding national forest, mapping fish-holding lies and productive patterns across dozens of drainages with obsessive precision. The shop offers wade trips into the park's most remote and productive corners, backcountry overnight fishing expeditions for anglers willing to hike past the road-accessible crowds, and instructional clinics focused specifically on the roll-casting and high-sticking techniques that Smokies fishing demands. The retail floor carries a tight selection of dry flies, nymphs, and terrestrials calibrated to mountain stream hatches — elk hair caddis, parachute Adams, stimulators, and the pheasant tail nymphs that rarely fail on the park's pocket water. For the fly angler seeking wild fish in a wilderness setting, Great Smoky Mountains National Park is an incomparable experience, and this shop is the key to unlocking it.",
