    description:
      "Headwaters Outfitters occupies a singular position among North Carolina fly shops — located in Brevard, within minutes of some of the finest mountain trout water in the eastern United States. The Davidson River corridor, with its iconic catch-and-release section managed by the US Forest Service, runs practically past the shop's back door, and DuPont State Recreational Forest's network of wild mountain streams lies minutes up the road. The French Broad River headwaters, the Mills River, and a constellation of national forest tributaries spread outward from Brevard in every direction, giving Headwaters Outfitters a home-water advantage that is unmatched in western North Carolina — they don't just know these rivers academically, they wade them before and after work.\n\nThe shop's guide program focuses specifically on the Brevard-area fisheries, offering both introductory instruction for first-time fly fishers on productive managed-access water and more technical outings on the Davidson's demanding catch-and-release section, where selective wild rainbows and browns require refined presentation and precise fly selection. The retail floor is anchored by a strong selection of 3 and 4-weight rods suited to the mountain stream environment, along with the emergers, dry flies, nymphs, and streamers that the Davidson and surrounding waters demand throughout the season. Guided paddling and fishing combination trips on the upper French Broad add a dimension not offered by most regional shops, and the staff's knowledge of DuPont's lesser-known wild stream tributaries is a competitive asset for experienced anglers who want to escape the Davidson's better-known pools.",
