  description: "Western Rivers Flyfisher is Utah's most storied fly shop — a Sugar House institution since 1986 that has spent nearly four decades at the center of the state's fly fishing culture. Located on 900 South in Salt Lake City, the shop serves as de facto headquarters for Utah's remarkable diversity of trout water: the Green River tailwater below Flaming Gorge, the Provo River below Deer Creek, the Weber River, the Logan River, and the high-altitude cutthroat lakes of the Uinta Mountains. No other shop in the state bridges as many rivers with as consistent a depth of expertise.\n\nThe retail operation is comprehensive and unapologetically premium — Winston, Scott, Simms, Patagonia, Hatch, and Hardy share floor space with an extensive fly selection curated for each specific water system. The guide service runs trips across the full spectrum of Utah's fisheries, with particular strength on the Green River tailwater at Dutch John and the Provo River corridor. Western Rivers also runs an international travel program, booking hosted fly-in adventures from Patagonia to Iceland at no additional fee to clients. Over 35 years, the shop has built a reputation that transcends retail: it's a clubhouse, a classroom, and a first stop before any serious Utah fly fishing expedition.",
