  destinationId: "dest-utah",
  description: "Spinner Fall Guide Service is one of the original Green River permit holders — a distinction that matters deeply on a tailwater that has been managed and protected since 1986 and whose permit structure limits commercial guide access. Operating out of Dutch John, Utah, just below the Flaming Gorge Dam, Spinner Fall has built its identity around the Green River's legendary fishery: mile after mile of gin-clear, 56-degree flows through red-rock canyon country, supporting one of the densest populations of wild trout in the United States. The A, B, and C sections below the dam each offer a distinct character, from technical dry-fly fishing to deep-nymphing the canyon's slower pools.\n\nSpinner Fall's small-company model means clients fish with experienced, dedicated guides who know the Green River intimately across all seasons and flow conditions. The guide service covers full-day and multi-day float trips, wade fishing, and can arrange lodging logistics in the Dutch John area. The Green River's consistent flows — dam-regulated and insulated from weather volatility — make it a reliable destination from March through November, with the prolific midge, Baetis, PMD, and Pale Evening Dun hatches providing year-round opportunity for technical dry-fly presentations.",
