  name: "Sweetgrass Rods",
  destinationId: "dest-montana",
  description: "Sweetgrass Rods is not a fly shop in the conventional sense — it is a bamboo rod atelier, a working studio where one of the most venerated craft traditions in fly fishing is practiced with museum-level precision. Founded by Glenn Brackett, whose 50-year career at the bench began under the master rod makers at the legendary R.L. Winston Rod Company (which he and Tom Morgan relocated from San Francisco to Twin Bridges, Montana in the mid-1970s to be closer to the Jefferson, Big Hole, Beaverhead, and Madison), Sweetgrass represents a direct lineage from the golden age of American cane rod making. The studio operates from Butte, Montana, by appointment, with a showroom that functions as both gallery and classroom.\n\nEach Sweetgrass rod begins as Arundinaria amabilis bamboo sourced directly from select Chinese growers and passes through an estimated 3,000 individual steps before leaving the shop — hand-splitting, oven treatment to achieve the signature honey-amber color, machine beveling, and final hand-finishing. The process takes 15 to 20 hours per rod. Brackett's signature \"Mantra\" series and custom commission rods are fished seriously by collectors and working anglers alike on the surrounding tailwaters and freestone streams. Visitors who call ahead are welcomed with impromptu casting sessions and tours of the workshop — a rare window into a craft practiced by fewer than a handful of makers at this level of quality anywhere in the world.",
